<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --blue: #3861FB;
  --navy: #0D1421;
  --gray: #808A9D;
  --green: #16c784;
  --red: #ea3943;
  --bg: #f8f9fc;
  --white: #ffffff;
  --border: #e5e7eb;
  --light-gray: #f1f3f5;
  --text-secondary: #64748b;
  --hover-bg: #f0f2f5;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--navy);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* Header / Nav */
.header {
  background: var(--white);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  height: 64px;
  gap: 24px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 18px;
  color: var(--navy);
  white-space: nowrap;
}
.logo-icon {
  width: 32px; height: 32px;
  background: var(--blue);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 16px;
  font-weight: 700;
}

.nav-links {
  display: flex;
  gap: 4px;
  flex: 1;
  overflow-x: auto;
}
.nav-link {
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  color: var(--navy);
  border-radius: 8px;
  white-space: nowrap;
  transition: background 0.15s;
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}
.nav-link:hover { background: var(--hover-bg); text-decoration: none; }
.nav-link.active { color: var(--blue); background: #eef1ff; }

.header-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.btn {
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  font-family: inherit;
  transition: all 0.15s;
  white-space: nowrap;
}
.btn-outline {
  background: transparent;
  border: 1.5px solid var(--border);
  color: var(--navy);
}
.btn-outline:hover { background: var(--hover-bg); }
.btn-primary {
  background: var(--blue);
  color: white;
}
.btn-primary:hover { opacity: 0.9; }

/* Top Bar Metrics */
.top-bar {
  max-width: 1400px;
  margin: 0 auto;
  padding: 16px 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.metric-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px 20px;
}
.metric-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--gray);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.metric-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--navy);
  font-variant-numeric: tabular-nums;
}
.metric-change {
  font-size: 13px;
  font-weight: 600;
  margin-top: 2px;
}
.metric-change.up { color: var(--green); }
.metric-change.down { color: var(--red); }

.metric-fg {
  display: flex;
  align-items: center;
  gap: 10px;
}
.fg-gauge {
  width: 48px; height: 48px;
  border-radius: 50%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 16px;
}
.fg-gauge.neutral {
  background: conic-gradient(#f0c040 0deg 205deg, #e5e7eb 205deg 360deg);
}
.fg-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--navy);
}

.fg-inner {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
}

.altcoin-bar {
  margin-top: 4px;
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(to right, #f0c040 37%, var(--blue) 37%, var(--blue) 100%);
  width: 100%;
}
.altcoin-labels {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--gray);
  margin-top: 4px;
}

/* Promo Banner */
.promo-banner {
  max-width: 1400px;
  margin: 0 auto 16px;
  padding: 0 24px;
}
.promo-inner {
  background: linear-gradient(135deg, #1a1f2e 0%, #2d3a5c 100%);
  border-radius: 12px;
  padding: 20px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: white;
  position: relative;
  overflow: hidden;
}
.promo-slides { flex: 1; }
.promo-slide {
  display: none;
  align-items: center;
  gap: 12px;
}
.promo-slide.active { display: flex; }
.promo-icon {
  background: rgba(255,255,255,0.15);
  border-radius: 10px;
  padding: 10px;
  font-size: 24px;
  flex-shrink: 0;
}
.promo-title { font-weight: 700; font-size: 16px; }
.promo-sub { font-size: 13px; opacity: 0.7; margin-top: 2px; }
.promo-cta {
  background: white;
  color: var(--navy);
  padding: 10px 20px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 14px;
  border: none;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
}
.promo-arrows {
  display: flex;
  gap: 6px;
  margin-left: 16px;
}
.promo-arrow {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  color: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: background 0.15s;
}
.promo-arrow:hover { background: rgba(255,255,255,0.35); }
.promo-dots {
  display: flex;
  gap: 6px;
  margin-left: 12px;
}
.promo-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
  border: none;
  cursor: pointer;
  padding: 0;
}
.promo-dot.active { background: white; }

/* AI Alerts Bar */
.ai-bar {
  max-width: 1400px;
  margin: 0 auto 16px;
  padding: 0 24px;
}
.ai-inner {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.ai-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--blue);
  background: #eef1ff;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
}
.ai-prompt {
  font-size: 14px;
  font-weight: 500;
  color: var(--navy);
}
.ai-suggestions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-left: auto;
}
.ai-chip {
  font-size: 12px;
  padding: 6px 12px;
  border-radius: 20px;
  background: var(--light-gray);
  border: 1px solid var(--border);
  cursor: pointer;
  font-family: inherit;
  color: var(--navy);
  font-weight: 500;
  transition: all 0.15s;
  white-space: nowrap;
}
.ai-chip:hover { background: #e0e3e8; }

/* Main content */
.main-content {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Network Filter Tabs */
.network-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}
.network-tab {
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--navy);
  font-family: inherit;
  transition: all 0.15s;
}
.network-tab:hover { background: var(--hover-bg); }
.network-tab.active {
  background: var(--blue);
  color: white;
  border-color: var(--blue);
}

/* Table Controls Bar */
.table-controls {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 20px;
  margin-bottom: 16px;
}

/* Category Tabs */
.category-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.category-tab {
  padding: 7px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--gray);
  font-family: inherit;
  transition: all 0.15s;
}
.category-tab:hover { color: var(--navy); background: var(--hover-bg); }
.category-tab.active {
  color: var(--blue);
  background: #eef1ff;
}

.controls-row {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.control-btn {
  padding: 7px 14px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--navy);
  font-family: inherit;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s;
}
.control-btn:hover { background: var(--hover-bg); }
.control-btn .arrow { font-size: 10px; }

/* Dropdown / Panel */
.dropdown-panel {
  display: none;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 20px;
  margin-top: 10px;
}
.dropdown-panel.open { display: block; }

.col-toggle-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 8px;
}
.col-toggle-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  padding: 6px 10px;
  border-radius: 6px;
  transition: background 0.15s;
}
.col-toggle-item:hover { background: var(--hover-bg); }
.col-toggle-item input { accent-color: var(--blue); }

.filter-panel-inner {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.filter-group label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--gray);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.filter-group input, .filter-group select {
  width: 100%;
  padding: 8px 12px;
  border: 1.5px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
  font-family: inherit;
  color: var(--navy);
  background: var(--white);
}
.filter-actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
  justify-content: flex-end;
}

/* Price change colors */
.pct-up { color: var(--green); }
.pct-down { color: var(--red); }

/* Table */
.table-container {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}

/* Index Tracker Row */
.index-row {
  display: grid;
  grid-template-columns: 40px minmax(140px, 2fr) repeat(3, minmax(90px, 1fr)) minmax(110px, 1.5fr) minmax(110px, 1.5fr) minmax(130px, 1.5fr) 120px;
  align-items: center;
  padding: 14px 20px;
  background: #fafbff;
  border-bottom: 2px solid var(--blue);
  font-size: 14px;
}
.index-row .col-num { font-weight: 700; color: var(--blue); }
.index-row .col-name { font-weight: 700; }
.index-tag {
  font-size: 10px;
  background: #eef1ff;
  color: var(--blue);
  padding: 2px 8px;
  border-radius: 4px;
  margin-left: 8px;
  font-weight: 600;
}

.crypto-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: auto;
}
.crypto-table thead { position: sticky; top: 64px; z-index: 10; }
.crypto-table th {
  text-align: right;
  padding: 12px 16px;
  font-size: 11px;
  font-weight: 700;
  color: var(--gray);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
}
.crypto-table th:hover { color: var(--navy); }
.crypto-table th:first-child { text-align: center; }
.crypto-table th:nth-child(2) { text-align: left; }
.crypto-table th .sort-icon { margin-left: 4px; font-size: 10px; }

.crypto-table td {
  padding: 12px 16px;
  font-size: 13px;
  font-weight: 500;
  text-align: right;
  border-bottom: 1px solid #f1f3f5;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.crypto-table td:first-child { text-align: center; }
.crypto-table td:nth-child(2) { text-align: left; }

.crypto-table tbody tr { transition: background 0.1s; }
.crypto-table tbody tr:hover { background: #fafbfc; }

.col-rank { width: 40px; color: var(--gray); font-weight: 600; }
.col-name-cell { display: flex; align-items: center; gap: 10px; }
.coin-icon {
  width: 28px; height: 28px;
  border-radius: 50%;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: white;
}
.coin-name { font-weight: 600; color: var(--navy); }
.coin-symbol { font-size: 12px; color: var(--gray); margin-left: 6px; }

/* Sparkline */
.sparkline-svg { width: 90px; height: 32px; }

/* Pagination */
.pagination-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-top: 1px solid var(--border);
  gap: 16px;
  flex-wrap: wrap;
}
.pagination-info { font-size: 13px; color: var(--gray); }
.pagination-pages {
  display: flex;
  gap: 2px;
  flex-wrap: wrap;
}
.page-btn {
  min-width: 36px; height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--white);
  color: var(--navy);
  font-family: inherit;
  transition: all 0.15s;
}
.page-btn:hover { background: var(--hover-bg); }
.page-btn.active {
  background: var(--blue);
  color: white;
  border-color: var(--blue);
}
.page-btn.ellipsis {
  border: none;
  background: transparent;
  cursor: default;
  color: var(--gray);
}

/* Market Summary */
.market-summary {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px 24px;
  margin: 20px 0;
}
.market-summary h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--navy);
}
.market-summary p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
}
.market-summary strong { color: var(--navy); }
.read-more-btn {
  margin-top: 12px;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--blue);
  font-family: inherit;
  display: flex;
  align-items: center;
  gap: 6px;
}
.read-more-btn:hover { background: #eef1ff; }
.market-expanded {
  display: none;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
}
.market-expanded.open { display: block; }
.market-expanded p { font-size: 14px; color: var(--text-secondary); line-height: 1.7; margin-bottom: 8px; }

/* Info Content */
.info-content {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 28px 24px;
  margin: 20px 0;
}
.info-content h2 {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 24px;
  color: var(--navy);
}
.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 24px;
}
.info-card h4 {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--navy);
}
.info-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* Footer */
.footer {
  background: var(--white);
  border-top: 1px solid var(--border);
  margin-top: 32px;
  padding: 40px 24px 24px;
}
.footer-grid {
  max-width: 1400px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--navy);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}
.footer-col a {
  display: block;
  font-size: 13px;
  color: var(--gray);
  margin-bottom: 8px;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--navy); text-decoration: none; }
.footer-bottom {
  max-width: 1400px;
  margin: 24px auto 0;
  padding-top: 16px;
  border-top: 1px solid var(--border);
  font-size: 12px;
  color: var(--gray);
}

/* Responsive */
@media (max-width: 1024px) {
  .top-bar { grid-template-columns: repeat(2, 1fr); }
  .crypto-table { font-size: 12px; }
  .crypto-table th, .crypto-table td { padding: 10px 10px; }
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .index-row { grid-template-columns: 40px minmax(100px, 2fr) repeat(3, minmax(60px, 1fr)) minmax(90px, 1.5fr) minmax(90px, 1.5fr) minmax(100px, 1.5fr) 100px; font-size: 13px; }
}

@media (max-width: 640px) {
  .top-bar { grid-template-columns: 1fr; }
  .header-inner { padding: 0 12px; gap: 12px; }
  .ai-suggestions { margin-left: 0; }
  .pagination-bar { flex-direction: column; align-items: flex-start; }
  .promo-inner { flex-direction: column; gap: 12px; text-align: center; }
  .promo-arrows { margin-left: 0; }
}
</style>
</head>
