// ── State ───────────────────────────────────────────────────
let currentCategory = 'top';
let currentNetwork = 'all';
let currentPage = 1;
let rowsPerPage = 100;
let activeFilters = {};
let hiddenCols = new Set();

// ── Render Table ────────────────────────────────────────────
function getFilteredData() {
  let data = [...cryptoData];

  // Network filter
  if (currentNetwork !== 'all') {
    data = data.filter(c => c.network === currentNetwork || c.network === 'all');
  }

  // Category filter (simulated — different sort orders / subsets)
  switch (currentCategory) {
    case 'trending':
      data.sort((a, b) => Math.abs(b.h24) - Math.abs(a.h24));
      break;
    case 'watchlist':
      data = data.filter(c => [1,2,4,7,10,13,15,21,25,34].includes(c.rank));
      break;
    case 'prediction':
      data = data.filter((_, i) => i % 4 === 0);
      break;
    case 'visited':
      data.sort((a, b) => b.vol - a.vol);
      break;
    case 'new':
      data = data.filter((_, i) => i >= 70);
      break;
    default: // top — sort by rank
      data.sort((a, b) => a.rank - b.rank);
  }

  // Apply column filters
  if (activeFilters.minPrice) data = data.filter(c => c.price >= activeFilters.minPrice);
  if (activeFilters.maxPrice) data = data.filter(c => c.price <= activeFilters.maxPrice);
  if (activeFilters.h24 === 'up') data = data.filter(c => c.h24 >= 0);
  if (activeFilters.h24 === 'down') data = data.filter(c => c.h24 < 0);

  return data;
}

function renderTable() {
  const data = getFilteredData();
  const totalPages = Math.ceil(data.length / rowsPerPage);
  if (currentPage > totalPages) currentPage = Math.max(1, totalPages);
  const start = (currentPage - 1) * rowsPerPage;
  const pageData = data.slice(start, start + rowsPerPage);

  const tbody = document.getElementById('tableBody');
  let html = '';

  pageData.forEach((c, idx) => {
    const spark = sparklineSVG(c.spark, c.d7 >= 0);
    const color = getCoinColor(idx);
    html += '<tr>';
    if (!hiddenCols.has('rank')) html += '<td class="col-rank">' + (start + idx + 1) + '</td>';
    if (!hiddenCols.has('name')) html += '<td><div class="col-name-cell"><div class="coin-icon" style="background:' + color + '">' + c.symbol.slice(0,2) + '</div><span class="coin-name">' + c.name + '</span><span class="coin-symbol">' + c.symbol + '</span></div></td>';
    if (!hiddenCols.has('price')) html += '<td style="text-align:right">' + fmtPrice(c.price) + '</td>';
    if (!hiddenCols.has('h1')) html += '<td class="' + pctClass(c.h1) + '">' + fmtPct(c.h1) + '</td>';
    if (!hiddenCols.has('h24')) html += '<td class="' + pctClass(c.h24) + '">' + fmtPct(c.h24) + '</td>';
    if (!hiddenCols.has('d7')) html += '<td class="' + pctClass(c.d7) + '">' + fmtPct(c.d7) + '</td>';
    if (!hiddenCols.has('marketcap')) html += '<td style="text-align:right">' + fmtMcap(c.mcap) + '</td>';
    if (!hiddenCols.has('volume')) html += '<td style="text-align:right">' + fmtVol(c.vol) + '</td>';
    if (!hiddenCols.has('supply')) html += '<td style="text-align:right">' + c.supply + '</td>';
    if (!hiddenCols.has('sparkline')) html += '<td style="text-align:right">' + spark + '</td>';
    html += '</tr>';
  });

  tbody.innerHTML = html;

  // Update range text
  document.getElementById('rangeStart').textContent = data.length > 0 ? start + 1 : 0;
  document.getElementById('rangeEnd').textContent = Math.min(start + rowsPerPage, data.length);

  // Render pagination
  renderPagination(totalPages);

  // Update column visibility on header
  updateHeaderVisibility();
}

function updateHeaderVisibility() {
  const headers = document.querySelectorAll('#cryptoTable thead th');
  const colMap = ['rank','name','price','h1','h24','d7','marketcap','volume','supply','sparkline'];
  headers.forEach((th, i) => {
    th.style.display = hiddenCols.has(colMap[i]) ? 'none' : '';
  });
  // Also update index row
  const indexCells = document.querySelectorAll('.index-row > div');
  indexCells.forEach((div, i) => {
    if (i < colMap.length) {
      div.style.display = hiddenCols.has(colMap[i]) ? 'none' : '';
    }
  });
}

function renderPagination(totalPages) {
  const container = document.getElementById('paginationPages');
  let html = '';

  // Previous
  html += '<button class="page-btn" ' + (currentPage === 1 ? 'disabled' : '') + ' data-page="' + (currentPage - 1) + '">&laquo;</button>';

  const maxButtons = 9;
  let pages = [];
  if (totalPages <= maxButtons) {
    for (let i = 1; i <= totalPages; i++) pages.push(i);
  } else {
    pages.push(1);
    if (currentPage > 4) pages.push('...');
    const s = Math.max(2, currentPage - 2);
    const e = Math.min(totalPages - 1, currentPage + 2);
    for (let i = s; i <= e; i++) pages.push(i);
    if (currentPage < totalPages - 3) pages.push('...');
    pages.push(totalPages);
  }

  pages.forEach(p => {
    if (p === '...') {
      html += '<span class="page-btn ellipsis">...</span>';
    } else {
      html += '<button class="page-btn' + (p === currentPage ? ' active' : '') + '" data-page="' + p + '">' + p + '</button>';
    }
  });

  // Next
  html += '<button class="page-btn" ' + (currentPage === totalPages ? 'disabled' : '') + ' data-page="' + (currentPage + 1) + '">&raquo;</button>';

  container.innerHTML = html;

  // Add click handlers
  container.querySelectorAll('.page-btn[data-page]').forEach(btn => {
    btn.addEventListener('click', function() {
      const p = parseInt(this.dataset.page);
      if (p >= 1 && p <= totalPages) {
        currentPage = p;
        renderTable();
        document.querySelector('.table-container').scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });
}

// ── Column Toggle ───────────────────────────────────────────
document.getElementById('btnColumns').addEventListener('click', function(e) {
  e.stopPropagation();
  const panel = document.getElementById('columnsPanel');
