  document.getElementById('filtersPanel').classList.remove('open');
});

// Close panels when clicking outside
document.addEventListener('click', function(e) {
  if (!e.target.closest('#columnsPanel') && !e.target.closest('#btnColumns')) {
    document.getElementById('columnsPanel').classList.remove('open');
  }
  if (!e.target.closest('#filtersPanel') && !e.target.closest('#btnFilters')) {
    document.getElementById('filtersPanel').classList.remove('open');
  }
});

// ── Category Tabs ───────────────────────────────────────────
document.getElementById('categoryTabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('category-tab')) {
    document.querySelectorAll('#categoryTabs .category-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
