  }
});

// ── Network Filter Tabs ─────────────────────────────────────
document.getElementById('networkTabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('network-tab')) {
    document.querySelectorAll('#networkTabs .network-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    currentNetwork = e.target.dataset.network;
    currentPage = 1;
    renderTable();
  }
});

// ── Navigation ──────────────────────────────────────────────
document.getElementById('mainNav').addEventListener('click', function(e) {
  if (e.target.classList.contains('nav-link')) {
    document.querySelectorAll('#mainNav .nav-link').forEach(l => l.classList.remove('active'));
    e.target.classList.add('active');
  }
});

// ── Promo Carousel ──────────────────────────────────────────
let promoSlide = 0;
const promoSldies = document.querySelectorAll('.promo-slide');
const promoDots = document.querySelectorAll('.promo-dot');

function showPromoSlide(n) {
  promoSldies.forEach(s => s.classList.remove('active'));
  promoDots.forEach(d => d.classList.remove('active'));
  promoSldies[n].classList.add('active');
  promoDots[n].classList.add('active');
  promoSlide = n;
}

document.getElementById('promoPrev').addEventListener('click', () => {
  showPromoSlide((promoSlide - 1 + promoSldies.length) % promoSldies.length);
});
document.getElementById('promoNext').addEventListener('click', () => {
