});
promoDots.forEach(dot => {
  dot.addEventListener('click', () => showPromoSlide(parseInt(dot.dataset.dot)));
});

// Auto rotate
setInterval(() => {
  showPromoSlide((promoSlide + 1) % promoSldies.length);
}, 5000);

// ── Market Summary Accordion ────────────────────────────────
document.getElementById('readMoreBtn').addEventListener('click', function() {
  const panel = document.getElementById('marketExpanded');
