// ── Table Header Sort ───────────────────────────────────────
document.querySelector('#cryptoTable thead').addEventListener('click', function(e) {
  const th = e.target.closest('th');
  if (!th) return;
  const col = th.dataset.col;
  const data = getFilteredData();
  if (col === 'rank' || col === 'name') {
    data.sort((a, b) => col === 'rank' ? a.rank - b.rank : a.name.localeCompare(b.name));
  } else if (col === 'price' || col === 'marketcap' || col === 'volume') {
    data.sort((a, b) => b[col === 'marketcap' ? 'mcap' : col === 'volume' ? 'vol' : 'price'] - a[col === 'marketcap' ? 'mcap' : col === 'volume' ? 'vol' : 'price']);
  } else if (col === 'supply') {
    data.sort((a, b) => a.name.localeCompare(b.name));
  } else {
    // percentage columns
    data.sort((a, b) => b[col] - a[col]);
  }
  // Update cryptoData order
  for (let i = 0; i < data.length; i++) {
    data[i].rank = i + 1;
  }
  cryptoData.splice(0, cryptoData.length, ...data);
  currentPage = 1;
  renderTable();
});

// ── Initial Render ──────────────────────────────────────────
renderTable();
